import { readFileSync } from 'node:fs';
const config = JSON.parse(readFileSync(new URL('../format.json', import.meta.url), 'utf8'));
export function formatLabel(value) {
  if (!value.trim()) throw new Error('blank label');
  return value.trim();
}
export function decoratedLabel(value) { return formatLabel(value) + config.suffix; }

